// === Tab: mySketch ===
// For the #WCCChallenge «Layers» (join the discord! https://discord.gg/S8c7qcjw2b)
//
// Draw a snowy mountain landscape
// The mountains are drawn using a point moving downwards along a noise field, with lines emanating from the point. Adding some randomness to give texture

let noiseScale = 0.01
let gravity = 0.03
let initialPoints = []
let currentPointIndex = 0
let previousPointIndex = -1
let isDone = false
let mountainFrameCount = 0 // Frame counter per mountain, resets when mountain restarts
let gen // Generator for progressive rendering

function setup() {
  createCanvas(windowWidth, windowHeight)
  pixelDensity(1)
  background(200)

  generateInitialPoints()
  gen = drawScene()
}

function generateInitialPoints() {
  let numPoints = random([4, 5, 6, 7])
  let minDistance = max(width, height) / 6
  let attempts = 0
  let maxAttempts = 1000

  initialPoints = []

  let _wG_1 = 0; while ((initialPoints.length < numPoints && attempts < maxAttempts) && ++_wG_1 < 20000) {
    let newPoint = {
      x: random(width / 5, (width * 4) / 5),
      y: random(height / 10, height * 2 / 3),
      vx: 0,
      vy: 0,
      previousX: 0,
    }
    newPoint.previousX = newPoint.x

    // Check if point is far enough from existing points
    let valid = true
    for (let existingPoint of initialPoints) {
      let d = dist(newPoint.x, newPoint.y, existingPoint.x, existingPoint.y)
      if (d < minDistance) {
        valid = false
        break
      }
    }

    if (valid) {
      initialPoints.push(newPoint)
    }

    attempts++
  }
  // Sort points by y position
  initialPoints = initialPoints.sort((a, b) => a.y - b.y)
}

function edgeBiasedRandom(centerMin = 0.3) {
  let _wG_2 = 0; while ((true) && ++_wG_2 < 20000) {
    const u = Math.random() // candidate value in [0, 1]
    const y = Math.random() // threshold in [0, 1]

    // Parabolic weight: max 1 at edges, min `centerMin` at center
    const w = centerMin + (1 - centerMin) * 4 * Math.pow(u - 0.5, 2)

    if (y < w) {
      return u // accepted
    }
    // else: reject and try again
  }
}

function updateParticle(point) {
  if (point.y >= height) return

  // Calculate noise detail based on y position
  let yNorm = point.y / height
  let nDetail = map(yNorm, 0, 1, 0.01, 1.5)

  // Get noise values based on position and frame
  let noiseX = noise(
    point.x * noiseScale,
    point.y * noiseScale,
    mountainFrameCount * 0.01,
  )
  let noiseY = noise(
    point.x * noiseScale + 100,
    point.y * noiseScale + 100,
    mountainFrameCount * 0.01,
  )

  // Map noise to angle and magnitude
  let angle = map(noiseX, 0, 1, -PI, PI)
  let normalizedX = abs(noiseY - 0.5) * 2
  normalizedX = normalizedX ** 2.5
  normalizedX = (1 - normalizedX) * (noiseY > 0.5 ? 1 : -1)
  let magnitude = normalizedX * nDetail

  // Apply noise-based force
  point.vx += cos(angle) * magnitude * 0.3
  point.vy += sin(angle) * magnitude * 0.1

  // Apply gravity
  point.vy += gravity

  // Update position
  point.x += point.vx
  point.y += point.vy

  // Apply damping
  point.vx *= 0.95
  point.vy *= 0.95
}

function handleMountainTransition() {
  // Check if point reached limits and switch to next
  let mPoint = initialPoints[currentPointIndex]
  if (mPoint.x < -width / 4 || mPoint.x > (width * 5) / 4 || mPoint.y >= height) {
    currentPointIndex = currentPointIndex + 1
    if (currentPointIndex >= initialPoints.length) {
      isDone = true
    }
  }

  // Check if this is a new point
  let isNewPoint = currentPointIndex !== previousPointIndex

  // Reset frame counter when starting a new mountain
  if (isNewPoint) {
    mountainFrameCount = 0
  }

  // Increment frame counter
  mountainFrameCount++

  // Add semi-transparent white overlay between mountain layers
  if (isNewPoint && currentPointIndex > 0) {
    fill(255, 255, 255, 255 * random(0.03, 0.08))
    noStroke()
    rect(0, 0, width, height)
  }

  previousPointIndex = currentPointIndex
  return isNewPoint
}

function generateAngles(T, minAngle, maxAngle, numLines = 60) {
  let angles = []
  for (let i = 0; i < numLines; i++) {
    let r = edgeBiasedRandom(0.2)
    let angle = map(r, 0, 1, minAngle, maxAngle)
    let a = angle < T ? map(angle, PI / 8, T, PI / 6, T) : angle
    angles.push(a)
  }
  angles.sort((a, b) => a - b)
  return angles
}

function maybeDrawBoulder(point, x, y, angle, T, maxAngle) {
  if (angle < T || abs(angle - maxAngle) <= PI / 50) return

  // Use noise to create clusters
  let noiseScale = 10
  let mountainOffset = currentPointIndex * 100
  let noiseValue = noise(x * noiseScale, y * noiseScale, mountainOffset)

  // Threshold for clustering
  let noiseThreshold = 0.7
  let noiseChance =
    noiseValue > noiseThreshold
      ? (noiseValue - noiseThreshold) / (1 - noiseThreshold)
      : 0

  // Combine noise-based chance with random chance
  let randomChance = 0.005
  let totalChance = noiseChance * 0.1 + randomChance

  if (random() < totalChance) {
    // Calculate size based on distance from origin
    let distFromOrigin = dist(point.x, point.y, x, y)
    let maxDist = sqrt(width * width + height * height)
    let normalizedDist = distFromOrigin / maxDist
    let objectSize = map(normalizedDist, 0, 1, 0.3, 1.0)

    drawBoulder(x, y, objectSize)
  }
}

function drawSegmentedLine(
  point,
  angle,
  capturePath,
  T,
  midAngle,
  maxAngle,
  lineIndex,
) {
  drawingContext.setLineDash([
    random(20, 40),
    random(5, 10),
    random(20, 40),
    random(5, 10),
    random(20, 40),
    random(5, 10),
  ])

  // Color: black if angle < T, gray otherwise
  if (angle < T) {
    stroke(40 + random(-30, 30))
  } else {
    stroke(225 + random(-30, 30))
  }

  let currentX = point.x
  let currentY = point.y
  let currentAngle = angle
  let segmentIndex = 0
  let totalLength = 0
  let path = capturePath ? [{ x: currentX, y: currentY }] : null

  let _wG_3 = 0; while ((true) && ++_wG_3 < 20000) {
    // Check if starting point is outside canvas
    if (
      currentX < -width / 4 ||
      currentX > (width * 5) / 4 ||
      currentY < 0 ||
      currentY > height
    ) {
      break
    }

    let sw = map(totalLength, 0, 250, 1, 0.3, true)
    if (angle < T) {
      sw = sw * 3
    }
    strokeWeight(sw)

    // Calculate segment parameters based on distance from center
    let distToCenter = abs(currentAngle - midAngle)
    let minSegmentLength = map(distToCenter, 0, PI / 2, 10, 20)
    let maxSegmentLength = map(distToCenter, 0, PI / 2, 40, 80)
    let noiseRotationScale = map(distToCenter, 0, PI / 2, 0.1, 0.001)
    let rotationScale = map(distToCenter, 0, PI / 2, 5, 0.5)

    let segmentLength = random(minSegmentLength, maxSegmentLength)
    let nextX = currentX + cos(currentAngle) * segmentLength
    let nextY = currentY + sin(currentAngle) * segmentLength

    // Draw segment with random jitter
    let offsetX = random(-2, 6)
    let offsetY = random(-5, 5)
    line(currentX, currentY, nextX + offsetX, nextY + offsetY)

    // Maybe draw boulder on white side
    if (angle >= T) {
      maybeDrawBoulder(
        point,
        nextX + offsetX,
        nextY + offsetY,
        angle,
        T,
        maxAngle,
      )
    }

    // Capture path point
    if (path) {
      path.push({ x: nextX, y: nextY })
    }

    totalLength += segmentLength
    currentX = nextX
    currentY = nextY

    // Apply noise-based rotation
    let noiseValue = noise(
      currentX * noiseRotationScale,
      currentY * noiseRotationScale,
      currentPointIndex * 0.1 + lineIndex * 0.01 + segmentIndex * 0.05,
    )
    let rotation =
      (map(noiseValue, 0, 1, -rotationScale, rotationScale) * PI) / 180
    currentAngle += rotation
    currentAngle = constrain(currentAngle, 0, PI)
    segmentIndex++
  }

  return path
}

function extendPathToEdge(path, angle, isRightEdge) {
  if (path.length < 2) return { x: path[0].x, y: path[0].y }

  let last = path[path.length - 1]
  let dir = atan2(
    last.y - path[path.length - 2].y,
    last.x - path[path.length - 2].x,
  )

  let edgeX = isRightEdge ? (width * 5) / 4 : -width / 4
  let edgeY = last.y

  if (abs(cos(dir)) > 0.001) {
    edgeY = last.y + tan(dir) * (edgeX - last.x)
    if (edgeY < 0) {
      edgeY = 0
      edgeX = last.x + (edgeY - last.y) / tan(dir)
    } else if (edgeY > height) {
      edgeY = height
      edgeX = last.x + (edgeY - last.y) / tan(dir)
    }
  } else {
    edgeY = height
  }

  return { x: edgeX, y: edgeY }
}

function drawMountainPolygon(point, lowestPath, highestPath, angles) {
  // Extend paths to canvas edges
  let rightEdge = extendPathToEdge(lowestPath, angles[0], true)
  let leftEdge = extendPathToEdge(highestPath, angles[angles.length - 1], false)

  // Create polygon
  let polygon = []
  polygon.push({ x: point.x, y: point.y })
  for (let p of lowestPath) polygon.push(p)
  polygon.push({ x: rightEdge.x, y: rightEdge.y })
  polygon.push({ x: rightEdge.x, y: height })
  polygon.push({ x: leftEdge.x, y: height })
  polygon.push({ x: leftEdge.x, y: leftEdge.y })
  for (let i = highestPath.length - 1; i >= 0; i--)
    polygon.push(highestPath[i])

  // Create conic gradient
  let lowestAngle = angles[0]
  let highestAngle = angles[angles.length - 1]
  let gradient = drawingContext.createConicGradient(
    lowestAngle,
    point.x,
    point.y,
  )

  let angleRange = highestAngle - lowestAngle
  let highestOffset = angleRange / (2 * PI)

  gradient.addColorStop(0, "#000000")
  gradient.addColorStop(highestOffset, "#FFFFFF")
  gradient.addColorStop(1, "#000000")

  drawingContext.fillStyle = gradient
  noStroke()
  beginShape()
  for (let v of polygon) {
    vertex(v.x, v.y)
  }
  endShape(CLOSE)

  // Reset fill style
  drawingContext.fillStyle = "rgba(0, 0, 0, 0)"
  noFill()
}

function *drawClouds(density = 4, passes = 1, perFrame = 50) {
  // density: how many strokes per cell (1 = original-ish, 2 = twice as dense, etc.)
  // passes: how many times to redraw the whole cloud field (subtle build-up)
  // perFrame: how many cells to process before yielding

  const baseR = 240;
  const baseG = 240;
  const baseB = 240;
  const _step = 5;
  let counter = 0;

  for (let p = 0; p < passes; p++) {
    const begin = random(50); // each pass shifts the noise

    let i = 0;
    for (let x = 0; x < width; x += (Math.max(0.001, Math.abs(_step)) || 1)) {
      let j = 0;

      for (let y = 0; y < height * 2/3; y += (Math.max(0.001, Math.abs(_step)) || 1)) {
        const alphaMax = map(y, 0, height * 2/3, 255, 0);
        let n = noise(begin + i, begin + j);
        let alphaBase = map(n, 0.3, 1, 0, alphaMax);
        alphaBase = constrain(alphaBase, 0, 255);

        if (alphaBase > 5) {
          // Draw several strokes in this cell to increase density
          for (let k = 0; k < density; k++) {
            const _alpha = alphaBase * random(0.5, 1.0);

            let brightnessJitter = random(-10, 10);
            if (random() < 0.05) {
              brightnessJitter = random(-30, -80);
            }
            const r = constrain(baseR + brightnessJitter, 0, 255);
            const g = constrain(baseG + brightnessJitter, 0, 255);
            const b = constrain(baseB + brightnessJitter, 0, 255);

            strokeWeight(random(0.5, 3));
            stroke(r, g, b, _alpha);

            const len = random(10, 20);
            const angle = random(-PI / 10, PI / 10);

            const x1 = x + random(-5, 5);
            const y1 = y + random(-5, 5);
            const x2 = x1 + cos(angle) * len;
            const y2 = y1 + sin(angle) * len;
            line(x1, y1, x2, y2);

            // occasional crosshatch stroke
            if (random() < 0.5) {
              stroke(r, g, b, _alpha * 0.4);
              const angle2 = angle + random(-PI / 3, PI / 3);
              const x3 = x1 + cos(angle2) * (len * 0.6);
              const y3 = y1 + sin(angle2) * (len * 0.6);
              line(x1, y1, x3, y3);
            }
          }
        }

        j += 0.06;
        counter++;

        // Yield periodically to show progress
        if (counter % perFrame === 0) {
          yield 1;
        }
      }

      i += 0.01;
    }
  }
}


function drawGradientBackground() {
  // Create linear gradient from almost white at top to background color at middle
  let topColor = 200
  let bottomColor = 160
  let midPoint = height / 2

  let gradient = drawingContext.createLinearGradient(0, 0, 0, midPoint)
  gradient.addColorStop(0, `rgb(${topColor}, ${topColor}, ${topColor})`)
  gradient.addColorStop(1, `rgb(${bottomColor}, ${bottomColor}, ${bottomColor})`)

  drawingContext.fillStyle = gradient
  drawingContext.fillRect(0, 0, width, midPoint)

  // Fill rest with background color
  fill(bottomColor)
  noStroke()
  rect(0, midPoint, width, height - midPoint)

  // Reset fill style
  drawingContext.fillStyle = "rgba(0, 0, 0, 0)"
}

function *drawScene() {
  // Draw gradient background first
  drawGradientBackground()

  // Draw clouds progressively
  let cloudGen = drawClouds(4, 1, round(width/4))
  for (let _ of cloudGen) {
    yield 1
  }

  // Then draw mountains progressively
  let _wG_4 = 0; while ((!isDone) && ++_wG_4 < 20000) {
    // Get current point
    let mPoint = initialPoints[currentPointIndex]
    if (!mPoint) {
      isDone = true
      break
    }

    // Update particle physics
    updateParticle(mPoint)

    // Handle mountain transitions
    let isNewPoint = handleMountainTransition()

    // Get current point (may have changed)
    mPoint = initialPoints[currentPointIndex]
    if (!mPoint) {
      isDone = true
      break
    }

    // Calculate angle T and generate angles
    let T = PI / 2 + map(noise(mountainFrameCount * 0.02), 0, 1, -PI / 6, PI / 6)
    let minAngle = PI / 6
    let maxAngle = PI - PI / 8
    let midAngle = (minAngle + maxAngle) / 2
    let angles = generateAngles(T, minAngle, maxAngle, 60)

    // Capture paths on first frame
    let lowestPath = null
    let highestPath = null
    let capturePaths = isNewPoint

    // Draw lines emanating from current point, yielding periodically
    for (let i = 0; i < angles.length; i++) {
      let a = angles[i]
      let isLowest = i === 0
      let isHighest = i === angles.length - 1

      let path = drawSegmentedLine(
        mPoint,
        a,
        capturePaths && (isLowest || isHighest),
        T,
        midAngle,
        maxAngle,
        i,
      )

      // Store captured paths
      if (capturePaths) {
        if (isLowest) {
          lowestPath = path
        } else if (isHighest) {
          highestPath = path
        }
      }
    }

    // Draw polygon on first frame
    if (capturePaths && lowestPath && highestPath) {
      drawMountainPolygon(mPoint, lowestPath, highestPath, angles)
    }
    if (mountainFrameCount % 4 === 0) {
      yield 1
    }

  }
  yield 1
}

function draw() {
  if (!isDone && gen) {
    let v = gen.next()
    if (v.done) {
      isDone = true
    }
  }
}

function drawBoulder(x, y, size = 1.0) {
  push()
  translate(x, y)
  scale(1, -1)
  rotate(random(-PI/6, PI/6))
  let baseSize = random(5, 30) * size
  let deltas = [2 * size, 5 * size]
  fill(random(60, 120))
  noStroke()
  // stroke(random(60, 120))
  // noFill()
  beginShape()
  let angle = 0
  for (;angle < PI; angle += random(PI/10, PI/5)) {
    let cx = baseSize * cos(angle)
    let cy = baseSize * sin(angle) * 0.5
    vertex(cx + random(...deltas), cy + random(...deltas))
  }
  // Now backwards from the last angle to 0
  for (;angle > 0; angle -= random(PI/10, PI/5)) {
    let cx = baseSize * cos(angle)  
    let cy = baseSize * sin(angle) * 0.5
    vertex(cx - random(...deltas), cy - random(...deltas))
  }
  endShape(CLOSE)
  pop()
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
    window.clm = {
        tracker: class {
            init() {}
            start() {}
            track() { return []; }
            getCurrentPosition() { return []; }
            getScore() { return 0; }
        }
    };
}
if (typeof window.ml5 === 'undefined') {
    const ml5MockObj = {
        detectStart: function() {},
        features: { get: function() { return []; } },
        on: function() {},
        ready: Promise.resolve(),
        loadModel: Promise.resolve()
    };
    window.ml5 = {
        bodypix: function() { return ml5MockObj; },
        faceapi: function() { return ml5MockObj; },
        handpose: function() { return ml5MockObj; },
        poseNet: function() { return ml5MockObj; },
        objectDetector: function() { return ml5MockObj; }
    };
}
if (typeof window.aiptag === 'undefined') { window.aiptag = {}; }
if (typeof window.lime === 'undefined') { window.lime = {}; }

// 1.8 免疫 3D 物理引擎與高階渲染 (THREE.Group, Tone.js, p5.asciify, REGL, Voronoi, PolyK, qrcode, P5Capture) 缺失導致的崩潰
if (typeof window.THREE === 'undefined') {
    window.THREE = {
        Group: class {},
        Scene: class {},
        PerspectiveCamera: class {},
        WebGLRenderer: class { setSize() {} },
        Mesh: class {},
        BoxGeometry: class {}
    };
}
if (typeof window.Tone === 'undefined') {
    window.Tone = {
        Player: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Players: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Sampler: class { triggerAttackRelease() {} connect() {} toDestination() {} },
        Sequence: class { start() {} stop() {} },
        Transport: { start: function() {}, stop: function() {}, bpm: { value: 120 } }
    };
}
if (typeof window.createREGL === 'undefined') {
    window.createREGL = function() {
        const regl = function() {};
        regl.texture = function() { return { resize: function() {} }; };
        regl.buffer = function() { return { subdata: function() {} }; };
        regl.framebuffer = function() { return { use: function(cb) { cb(); } }; };
        return regl;
    };
}
if (typeof window.Voronoi === 'undefined') {
    window.Voronoi = class {
        compute() { return { cells: [], edges: [] }; }
    };
}
if (typeof window.qrcode === 'undefined') {
    window.qrcode = function(data) {
        return {
            createImgTag: function() { return ""; },
            createTableTag: function() { return ""; },
            createSvgTag: function() { return ""; }
        };
    };
    window.qrcode.stringToBytes = function(s) { return []; };
}
if (typeof window.PolyK === 'undefined') {
    window.PolyK = {
        Slice: function() { return []; },
        Triangulate: function() { return []; },
        getArea: function() { return 0; }
    };
}
if (typeof window.P5Capture === 'undefined') {
    window.P5Capture = {
        getInstance: function() {
            return { start: function() {}, stop: function() {}, setFormat: function() {} };
        },
        setDefaultOptions: function() {}
    };
}

// 1.9 免疫 OPC (OpenProcessing Controller) 與 WebGL 內部 setUniform 崩潰
if (typeof window.OPC === 'undefined') {
    window.OPC = {
        title: function() {},
        slider: function() {},
        button: function() {},
        toggle: function() {},
        color: function() {}
    };
}
if (typeof p5 !== 'undefined' && p5.Shader) {
    const origSetUniform = p5.Shader.prototype.setUniform;
    p5.Shader.prototype.setUniform = function(name, val) {
        if (!this) return this;
        try {
            return origSetUniform.call(this, name, val);
        } catch(e) {
            return this;
        }
    };
}

// 1.95 免疫某些特定遊戲模組對 parent / maeExportApis_ 或是唯讀屬性的寫入崩潰
try {
  if (typeof window.parent !== 'undefined') {
    if (!window.parent.maeExportApis_) {
      try {
        window.parent.maeExportApis_ = function() {};
      } catch(e) {}
    }
  }
} catch(e) {}

// 1.96 免疫 textmode 缺失以及 loadSVG / p5.SVG 插件型別拋錯
if (typeof textmode === 'undefined') { window.textmode = function() {}; }
if (typeof MAT === 'undefined') { window.MAT = []; }
if (typeof SIDES === 'undefined') { window.SIDES = 4; }
if (typeof GRIDBOX === 'undefined') { window.GRIDBOX = 10; }
if (typeof COLUMNS === 'undefined') { window.COLUMNS = 5; }
if (typeof tileSize === 'undefined') { window.tileSize = 30; }
if (typeof mouseTileX === 'undefined') { window.mouseTileX = 0; }
if (typeof p5 !== 'undefined') {
  if (!p5.prototype.loadSVG) {
    p5.prototype.loadSVG = function(path, success, failure) {
      if (success) success({});
      return {};
    };
  }
  // 免疫 window.VERSION 唯讀寫入錯誤
  try {
    Object.defineProperty(window, 'VERSION', {
      value: "p5-stub",
      writable: true,
      configurable: true
    });
  } catch(e) {}
}

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || path.startsWith('http') || (path.startsWith('data:') === false && path.indexOf('.') === -1)) {
            // 當發現是遠端 URL、相對路徑或格式無副檔名時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖與 CORS 錯誤
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };

    // 修正 img.loadPixels / img.resize 缺失與未非同步載入完成呼叫
    if (!p5.Image.prototype.loadPixels) { p5.Image.prototype.loadPixels = function() { return this; }; }
    if (!p5.Image.prototype.resize) { p5.Image.prototype.resize = function() { return this; }; }
    if (!p5.Image.prototype.get) { p5.Image.prototype.get = function() { return [0,0,0,255]; }; }
    if (!p5.Image.prototype.width) {
        Object.defineProperty(p5.Image.prototype, 'width', {
            get: function() { return this._width || 1280; },
            set: function(v) { this._width = v; }
        });
    }
    if (!p5.Image.prototype.height) {
        Object.defineProperty(p5.Image.prototype, 'height', {
            get: function() { return this._height || 720; },
            set: function(v) { this._height = v; }
        });
    }

    // 修正 p5.Graphics / p5.Renderer / Element.prototype.style
    if (p5.Graphics && p5.Graphics.prototype) {
        if (!p5.Graphics.prototype.loadPixels) { p5.Graphics.prototype.loadPixels = function() { return this; }; }
    }
}

// 2.2 修正 p5.Table / loadTable / getRowCount 缺失與錯誤
if (typeof p5 !== 'undefined' && p5.Table) {
    if (!p5.Table.prototype.getRowCount) { p5.Table.prototype.getRowCount = function() { return 0; }; }
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (!this || this.width === 0 || this.height === 0) {
            return [0,0,0,255];
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return [0,0,0,255];
        }
    };
}

